import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`marathon-training-dashboard`,heroTitle:`Build your marathon training dashboard in minutes`,heroSubtitle:`Perplexity Computer creates a personalized race plan, tracks your weekly progress, and sends smart training reminders — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Analyzing your race goals and fitness level`,`Building a personalized training plan with weekly milestones`,`Setting up progress tracking and smart reminders`,`Your marathon training dashboard is live — ready to train`],generatingSteps:[`Gathering race distance, goal time, and training preferences`,`Designing an agent to build a periodized training plan with adaptive weekly structure`,`Configuring progress tracking, mileage logs, and pace analysis`,`Setting up smart reminders and plan adjustments when life gets in the way`],featureSectionTitle:`From race goal to training dashboard`,featureCardTitles:[`Connects to your fitness stack`,`Outputs you can train on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Calendar, Slack, Notion — Computer logs your runs, schedules workouts, and sends reminders through the tools you already use.`,`Personalized weekly training plans. Pace and mileage dashboards. Recovery recommendations. Smart alerts when your plan needs adjusting.`],capabilitySectionTitle:`Your running coach, on autopilot`,capabilitySectionSubtitle:`Set your race goal, lace up, get a plan that adapts with you.`,capabilityCards:[{title:`Race Plan Builder`,description:`Computer can build a periodized marathon plan — base building, speed work, tapering — customized to your goal time, experience, and schedule.`},{title:`Weekly Progress Tracking`,description:`Computer can log your runs, track weekly mileage and pace trends, and surface whether you're on target or falling behind your plan.`},{title:`Adaptive Scheduling`,description:`Computer can adjust your training when life gets in the way — shifting workouts, redistributing mileage, and protecting your taper window.`},{title:`Connect Your Tools`,description:`Computer can sync with Google Sheets, Google Calendar, Notion, and Slack — build workflows across your entire training and scheduling stack.`},{title:`Remember & Improve`,description:`Computer can remember your training history, injury patterns, and performance data across sessions — so every plan update gets smarter over time.`},{title:`Monitor & Remind`,description:`Computer can check your training log daily and send reminders when you miss a workout, need recovery, or when your plan needs attention.`}]});export{t as default};
